import json
import os
from typing import Any, Dict, List, Optional

import boto3


def _normalize_polygon(points: Any) -> List[Dict[str, float]]:
    if not points:
        return []
    normalized = []
    for p in points:
        x = getattr(p, "X", None)
        y = getattr(p, "Y", None)
        if x is None and isinstance(p, dict):
            x = p.get("X", p.get("x"))
            y = p.get("Y", p.get("y"))
        if x is not None and y is not None:
            normalized.append({"x": float(x), "y": float(y)})
    return normalized


def _bbox_from_geometry(geometry: Any) -> Optional[Dict[str, float]]:
    if not geometry:
        return None
    polygon = getattr(geometry, "Polygon", None) or getattr(geometry, "polygon", None)
    points = _normalize_polygon(polygon)
    if not points:
        return None
    xs = [p["x"] for p in points]
    ys = [p["y"] for p in points]
    return {
        "left": min(xs),
        "top": min(ys),
        "width": max(xs) - min(xs),
        "height": max(ys) - min(ys),
    }


def extract_table_cells_and_rows(document_bytes: bytes, document_name: str = "document") -> Dict[str, Any]:
    """
    Extract tables, cells, and row structure from a document using Amazon Textract.

    Returns a JSON-serializable dictionary containing:
      - tables: list of tables with cells and row grouping
      - blocks: raw Textract block summary
    """
    textract = boto3.client("textract")

    response = textract.analyze_document(
        Document={"Bytes": document_bytes},
        FeatureTypes=["TABLES"],
    )

    blocks = response.get("Blocks", [])
    block_map = {b["Id"]: b for b in blocks if "Id" in b}

    tables_out: List[Dict[str, Any]] = []

    for block in blocks:
        if block.get("BlockType") != "TABLE":
            continue

        table_id = block.get("Id")
        relationships = block.get("Relationships", [])
        cell_ids: List[str] = []
        for rel in relationships:
            if rel.get("Type") == "CHILD":
                cell_ids.extend(rel.get("Ids", []))

        cells: List[Dict[str, Any]] = []
        row_map: Dict[int, List[Dict[str, Any]]] = {}

        for cell_id in cell_ids:
            cell = block_map.get(cell_id)
            if not cell or cell.get("BlockType") != "CELL":
                continue

            row_index = int(cell.get("RowIndex", 0))
            col_index = int(cell.get("ColumnIndex", 0))
            row_span = int(cell.get("RowSpan", 1))
            col_span = int(cell.get("ColumnSpan", 1))

            text_parts: List[str] = []
            for rel in cell.get("Relationships", []):
                if rel.get("Type") != "CHILD":
                    continue
                for child_id in rel.get("Ids", []):
                    child = block_map.get(child_id)
                    if not child:
                        continue
                    if child.get("BlockType") == "WORD":
                        if "Text" in child:
                            text_parts.append(child["Text"])
                    elif child.get("BlockType") == "SELECTION_ELEMENT":
                        if child.get("SelectionStatus") == "SELECTED":
                            text_parts.append("X")

            text = " ".join(text_parts).strip()
            cell_entry = {
                "row_index": row_index,
                "column_index": col_index,
                "row_span": row_span,
                "column_span": col_span,
                "text": text,
                "confidence": float(cell.get("Confidence", 0.0)),
                "bbox": _bbox_from_geometry(cell.get("Geometry")),
            }
            cells.append(cell_entry)
            row_map.setdefault(row_index, []).append(cell_entry)

        # Sort cells within each row by column index and rows by row index
        rows = []
        for row_index in sorted(row_map.keys()):
            row_cells = sorted(row_map[row_index], key=lambda c: (c["column_index"], c["row_index"]))
            rows.append(
                {
                    "row_index": row_index,
                    "cells": row_cells,
                    "texts": [c["text"] for c in row_cells],
                }
            )

        tables_out.append(
            {
                "table_id": table_id,
                "confidence": float(block.get("Confidence", 0.0)),
                "bbox": _bbox_from_geometry(block.get("Geometry")),
                "cells": sorted(cells, key=lambda c: (c["row_index"], c["column_index"])),
                "rows": rows,
            }
        )

    return {
        "document_name": document_name,
        "tables": tables_out,
        "blocks": {
            "count": len(blocks),
            "raw": blocks,
        },
        "model": "amazon-textract-analyze-document",
    }


def extract_table_cells_and_rows_from_file(path: str) -> Dict[str, Any]:
    with open(path, "rb") as f:
        data = f.read()
    return extract_table_cells_and_rows(data, document_name=os.path.basename(path))


def extract_table_cells_and_rows_from_json(document_bytes: bytes, document_name: str = "document") -> str:
    return json.dumps(extract_table_cells_and_rows(document_bytes, document_name=document_name), ensure_ascii=False)
